#!/usr/bin/env python3
"""Phase 1: candidates derived from unicodedata names of emoji-ish codepoints."""
import re, sys, unicodedata
sys.path.insert(0, "/tmp/probe/emoji")
import probe

STOP = {"with", "of", "and", "the", "a", "in", "on", "for", "to", "at"}
DROP_SUFFIX = ["face", "sign", "symbol", "button", "selector", "mark", "character",
               "ornament", "emoji", "modifier", "glyph", "shape"]

def norm(s):
    s = re.sub(r"[^a-z0-9]+", "_", s.lower()).strip("_")
    return re.sub(r"_+", "_", s)

def variants(nm):
    base = norm(nm)
    out = {base}
    w = base.split("_")
    out.add("_".join(x for x in w if x not in STOP))
    out.add(base.replace("_and_", "_"))
    for suf in DROP_SUFFIX:
        if len(w) > 1 and w[-1] == suf:
            out.add("_".join(w[:-1]))
            out.add("_".join(x for x in w[:-1] if x not in STOP))
    if len(w) > 1:
        out.add("_".join(reversed(w)))       # reordered
        out.add(w[-1])                        # last word alone
        out.add(w[0])                         # first word alone
        out.add("_".join(w[-2:]))             # last two
        out.add("_".join(w[:2]))              # first two
    return {x for x in out if x}

def main():
    cands = set()
    rngs = [(0x00A0, 0x00FF), (0x2000, 0x33FF), (0x1F000, 0x1FBFF)]
    for a, b in rngs:
        for cp in range(a, b + 1):
            try:
                nm = unicodedata.name(chr(cp))
            except ValueError:
                continue
            cands |= variants(nm)
    cands = {c for c in cands if re.fullmatch(r"[a-z0-9_]+", c)}
    print("phase1 candidates:", len(cands))
    probe.probe(sorted(cands))
    with open("/tmp/probe/emoji/found.tsv", "w") as f:
        for k, v in sorted(probe.STATE["found"].items()):
            f.write("%s\t%s\t%s\n" % (k, v, probe.cps(v)))

main()

